package mach.semantic;
import mach.ast.Ast.*;
import mach.frontend.Diagnostic;
import java.util.*;

/** Typed synchronous module contracts; host objects never escape without a MachOne type. */
public final class SystemContracts {
    private SystemContracts() {}
    public static final Set<String> MODULE_TYPES=Set.of("File","Path","Dir","Env","Process","System","Console","Json","Csv","Base64","Hex","Hash","Uuid","Url","Date","DateTime","FileHandle","Reflect","Debug","Log","Test","Bench");
    private static final Type ANY=new Type("any"),NIL=new Type("nil"),BOOL=new Type("bool"),INT=new Type("int"),LONG=new Type("long"),STR=new Type("str"),TAG=new Type("tag"),TYPE=new Type("type");
    private static Type vec(Type value){return new Type("vec",List.of(value));}private static Type obj(Type value){return new Type("obj",List.of(value));}private static Type maybe(Type value){return new Type("maybe",List.of(value));}private static Type attempt(Type value){return new Type("try",List.of(value));}
    private static void error(Span span,String text){throw new Diagnostic("M2101",span,text);}private static boolean fits(Type actual,Type expected){if(expected.equals(ANY)||actual.equals(expected))return true;if(expected.equals(TYPE)&&actual.name().equals("type"))return true;if(actual.name().equals(expected.name())&&actual.args().size()==expected.args().size()){for(int i=0;i<actual.args().size();i++)if(!fits(actual.args().get(i),expected.args().get(i)))return false;return true;}return false;}
    private static void args(Span span,List<Type> args,Type...expected){if(args.size()!=expected.length)throw new Diagnostic("M2201",span,"mensagem exige "+expected.length+" argumento(s)");for(int i=0;i<expected.length;i++)if(!fits(args.get(i),expected[i]))error(span,"tipo "+args.get(i)+" incompatível com "+expected[i]);}
    private static Type block(Span span,Type block,List<Type> inputs){if(block==null||!block.name().equals("lambda"))throw new Diagnostic("M2204",span,"mensagem exige bloco anônimo =>");if(block.args().size()!=inputs.size()+1)throw new Diagnostic("M2201",span,"aridade inválida do bloco");for(int i=0;i<inputs.size();i++)if(!fits(inputs.get(i),block.args().get(i)))error(span,"bloco não aceita "+inputs.get(i));return block.args().getLast();}
    public static List<Type> blockInputs(Type receiver,String selector,List<Type> args){if(receiver==null||!receiver.name().equals("type")||receiver.args().isEmpty())return null;return switch(receiver.args().getFirst().name()+"/"+selector){case "File/each_line"->List.of(STR);case "File/open:mode"->List.of(new Type("FileHandle"));case "Test/suite","Test/test","Bench/run:times"->List.of();default->null;};}
    public static Type resolve(Type receiver,String selector,List<Type> values,Type anonymous,Span span){
        if(receiver==null)return null;String module;if(receiver.name().equals("type")&&receiver.args().size()==1)module=receiver.args().getFirst().name();else return instance(receiver,selector,values,span);if(!MODULE_TYPES.contains(module))return null;
        switch(module){
            case "File":switch(selector){case "read":args(span,values,STR);return attempt(STR);case "read_lines":args(span,values,STR);return attempt(vec(STR));case "write:text","append:text","copy:to","move:to":args(span,values,STR,STR);return attempt(NIL);case "delete":args(span,values,STR);return attempt(NIL);case "size":args(span,values,STR);return attempt(LONG);case "exists?":args(span,values,STR);return BOOL;case "each_line":args(span,values,STR);block(span,anonymous,List.of(STR));return attempt(NIL);case "open:mode":args(span,values,STR,TAG);return attempt(block(span,anonymous,List.of(new Type("FileHandle"))));default:return null;}
            case "Path":switch(selector){case "join":if(values.isEmpty())throw new Diagnostic("M2201",span,"Path join exige argumento");for(Type value:values)args(span,List.of(value),STR);return STR;case "base","dir","ext","absolute":args(span,values,STR);return STR;case "exists?","file?","dir?":args(span,values,STR);return BOOL;default:return null;}
            case "Dir":switch(selector){case "cwd","home","tmp":args(span,values);return STR;case "list","glob":args(span,values,STR);return attempt(vec(STR));case "create","delete":args(span,values,STR);return attempt(NIL);default:return null;}
            case "Env":switch(selector){case "get":args(span,values,STR);return maybe(STR);case "set":args(span,values,STR,STR);return NIL;case "all":args(span,values);return obj(STR);default:return null;}
            case "Process":switch(selector){case "pid":args(span,values);return LONG;case "cwd":args(span,values);return STR;case "args":args(span,values);return vec(STR);case "exit":args(span,values,INT);return NIL;case "run:args":args(span,values,STR,vec(STR));return attempt(obj(ANY));default:return null;}
            case "System":switch(selector){case "os","arch","version":args(span,values);return STR;case "hostname":args(span,values);return attempt(STR);case "cpus":args(span,values);return INT;default:return null;}
            case "Console":switch(selector){case "clear":args(span,values);return NIL;case "width":args(span,values);return INT;case "color:text":args(span,values,TAG,STR);return NIL;default:return null;}
            case "Json":switch(selector){case "parse":args(span,values,STR);return attempt(obj(ANY));case "generate","pretty":args(span,values,ANY);if(!Set.of("nil","bool","byte","ubyte","short","ushort","int","uint","long","ulong","float","double","str","char","tag","vec","obj","any").contains(values.getFirst().name()))error(span,"JSON não serializa "+values.getFirst());return STR;default:return null;}
            case "Csv":switch(selector){case "parse:header":args(span,values,STR,BOOL);return attempt(vec(ANY));case "generate":args(span,values,vec(ANY));return attempt(STR);default:return null;}
            case "Base64","Hex":switch(selector){case "encode":args(span,values,STR);return STR;case "decode":args(span,values,STR);return attempt(STR);default:return null;}
            case "Hash":if(Set.of("sha256","sha1","md5").contains(selector)){args(span,values,STR);return STR;}return null;
            case "Uuid":switch(selector){case "v4":args(span,values);return STR;case "parse":args(span,values,STR);return attempt(STR);default:return null;}
            case "Url":switch(selector){case "encode":args(span,values,STR);return STR;case "decode":args(span,values,STR);return attempt(STR);case "parse":args(span,values,STR);return attempt(obj(ANY));default:return null;}
            case "Date":switch(selector){case "today":args(span,values);return new Type("Date");case "new":args(span,values,INT,INT,INT);return attempt(new Type("Date"));case "parse":args(span,values,STR);return attempt(new Type("Date"));default:return null;}
            case "DateTime":switch(selector){case "now","utc":args(span,values);return new Type("DateTime");case "parse":args(span,values,STR);return attempt(new Type("DateTime"));default:return null;}
            case "Reflect":switch(selector){case "methods":args(span,values,TYPE);return vec(TAG);case "attrs":args(span,values,TYPE);return vec(obj(ANY));case "supertypes","subtypes":args(span,values,TYPE);return vec(TYPE);case "responds_to":args(span,values,ANY,TAG);return BOOL;case "send":args(span,values,ANY,TAG,vec(ANY));return attempt(ANY);default:return null;}
            case "Debug":switch(selector){case "dump":args(span,values,ANY);return values.getFirst();case "trace":args(span,values);return vec(STR);case "assert:msg":args(span,values,BOOL,STR);return attempt(NIL);default:return null;}
            case "Log":if(Set.of("info","warn","error","debug").contains(selector)){args(span,values,STR);return NIL;}if(selector.equals("level")){args(span,values,TAG);return NIL;}return null;
            case "Test":switch(selector){case "suite","test":args(span,values,STR);block(span,anonymous,List.of());return NIL;case "expect:to_be":args(span,values,ANY,ANY);return attempt(NIL);case "expect_fail:kind":args(span,values,ANY,TAG);return attempt(NIL);case "run":args(span,values);return attempt(NIL);default:return null;}
            case "Bench":if(selector.equals("run:times")){args(span,values,STR,INT);block(span,anonymous,List.of());return attempt(obj(ANY));}return null;
            default:return null;
        }
    }
    private static Type instance(Type receiver,String selector,List<Type> values,Span span){
        if(receiver.name().equals("Date"))return switch(selector){case "year","month","day","weekday"->{args(span,values);yield INT;}case "leap?"->{args(span,values);yield BOOL;}case "to_str"->{args(span,values);yield STR;}case "add_days","add_months"->{args(span,values,INT);yield attempt(receiver);}case "format"->{args(span,values,STR);yield attempt(STR);}case "days_until"->{args(span,values,receiver);yield LONG;}case "<",">","<=",">="->{args(span,values,receiver);yield BOOL;}default->null;};
        if(receiver.name().equals("DateTime"))return switch(selector){case "year","month","day","hour","minute","second"->{args(span,values);yield INT;}case "to_unix"->{args(span,values);yield LONG;}case "utc"->{args(span,values);yield receiver;}case "to_str"->{args(span,values);yield STR;}case "zone"->{args(span,values,STR);yield attempt(receiver);}case "format"->{args(span,values,STR);yield attempt(STR);}default->null;};
        if(receiver.name().equals("FileHandle"))return switch(selector){case "read"->{args(span,values);yield attempt(STR);}case "write"->{args(span,values,STR);yield attempt(NIL);}case "path"->{args(span,values);yield STR;}default->null;};return null;
    }
}
